M._Translations = Translations

-- ============================================================
-- الحالة الداخلية + التحميل/الحفظ
-- ============================================================
local current = "en"

function M.Load()
    local ok, data = pcall(function()
        if isfile and isfile(FILE_NAME) then
            return HttpService:JSONDecode(readfile(FILE_NAME))
        end
        return nil
    end)
    if ok and type(data) == "table" and data.code and M.Languages[data.code] then
        current = data.code
        return true
    end
    return false
end

function M.Save(code)
    pcall(function()
        if writefile then
            writefile(FILE_NAME, HttpService:JSONEncode({ code = code }))
        end
    end)
end

function M.HasSaved()
    if not isfile then return false end
    local ok, exists = pcall(isfile, FILE_NAME)
    return ok and exists == true
end

function M.Set(code)
    if not M.Languages[code] then return false end
    current = code
    M.Save(code)
    return true
end

function M.Get()        return current end
function M.GetMeta()    return M.Languages[current] end
function M.GetAll()     return M.Languages end

-- ============================================================
-- T(key) → النص بلغة المستخدم، أو fallback إلى الإنجليزية، أو المفتاح نفسه
-- ============================================================
function M.T(key)
    local t = Translations[current]
    if t and t[key] ~= nil then return t[key] end
    if Translations.en[key] ~= nil then return Translations.en[key] end
    return key
end

-- T(key, lang) → بلغة محددة (للاستخدام في معاينة)
function M.TIn(key, lang)
    local t = Translations[lang]
    if t and t[key] ~= nil then return t[key] end
    if Translations.en[key] ~= nil then return Translations.en[key] end
    return key
end

-- إضافة/تجاوز ترجمات وقت التشغيل (للموديولات اللي تبي تسجل ترجماتها)
function M.Register(code, table_)
    if not Translations[code] then Translations[code] = {} end
    for k, v in pairs(table_) do
        Translations[code][k] = v
    end
end

return M
